WITH flattened AS (SELECT id, service, host, level, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, value) SELECT CASE WHEN latency_ms >= 1819 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, CASE WHEN status_code >= 389 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, SORT_ARRAY(COLLECT_SET(host)) AS host_list, SIZE(COLLECT_SET(level)) AS num_levels FROM flattened GROUP BY GROUPING SETS ((CASE WHEN latency_ms >= 1819 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN status_code >= 389 THEN 'LARGE' ELSE 'SMALL' END), (CASE WHEN latency_ms >= 1819 THEN 'HIGH' ELSE 'LOW' END), ()) HAVING SIZE(COLLECT_SET(level)) < 1000 ORDER BY latency_ms_tier;
